def panjang_terpanjang(s):
    posisi = {}
    kiri = 0
    terbaik = 0
    for kanan, ch in enumerate(s):
        if ch in posisi and posisi[ch] >= kiri:
            kiri = posisi[ch] + 1
        posisi[ch] = kanan
        terbaik = max(terbaik, kanan - kiri + 1)
    return terbaik
